solution:
def split(total, n):
    base, extra = divmod(total, n)
    return [base + 1 if i < extra else base for i in range(n)]

alt:
def split(total, n):
    shares = [total // n] * n
    for i in range(total % n):
        shares[i] += 1
    return shares
